source='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            min_r = min(y for y, _ in cells)
            max_r = max(y for y, _ in cells)
            min_c = min(x for _, x in cells)
            max_c = max(x for _, x in cells)
            local = {(y - min_r, x - min_c) for y, x in cells}
            bh, bw = max_r - min_r + 1, max_c - min_c + 1
            outside = set()
            queue = deque()
            for yy in range(bh):
                for xx in range(bw):
                    if (yy, xx) not in local and (yy in (0, bh - 1) or xx in (0, bw - 1)):
                        outside.add((yy, xx))
                        queue.append((yy, xx))
            while queue:
                yy, xx = queue.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = yy + dy, xx + dx
                    if 0 <= ny < bh and 0 <= nx < bw and (ny, nx) not in local and (ny, nx) not in outside:
                        outside.add((ny, nx))
                        queue.append((ny, nx))
            hollow = any((yy, xx) not in local and (yy, xx) not in outside
                         for yy in range(bh) for xx in range(bw))
            objects.append({"cells": cells, "top": min_r, "bottom": max_r, "hollow": hollow})

    result = [[0] * w for _ in range(h)]
    for hollow in (True, False):
        group = [obj for obj in objects if obj["hollow"] == hollow]
        if hollow:
            group.sort(key=lambda obj: obj["top"])
            placed = []
            for obj in group:
                local = [(y - obj["top"], x) for y, x in obj["cells"]]
                shift = 0
                while any((y + shift, x) in occupied for y, x in local for occupied in placed):
                    shift += 1
                positioned = {(y + shift, x) for y, x in local}
                placed.append(positioned)
                color = grid[obj["cells"][0][0]][obj["cells"][0][1]]
                for y, x in positioned:
                    result[y][x] = color
        else:
            group.sort(key=lambda obj: obj["bottom"], reverse=True)
            placed = []
            for obj in group:
                local = [(y - obj["top"], x) for y, x in obj["cells"]]
                shift = h - 1 - obj["bottom"]
                while any((y + shift, x) in occupied for y, x in local for occupied in placed):
                    shift -= 1
                positioned = {(y + shift, x) for y, x in local}
                placed.append(positioned)
                color = grid[obj["cells"][0][0]][obj["cells"][0][1]]
                for y, x in positioned:
                    result[y][x] = color
    return result
